#!/usr/bin/env python3
# Generated by Claude Opus 4.8 (claude.ai/code) · 2026-09-01
"""Search activities in a Mynatime profile.json and total the time spent.

Reads the committed activities (`Commits.Items`) of a profile and sums the hours,
optionally filtered by category, comment text, and/or date range. Handles both
activity forms: `MynatimeCLI.ActivityStartStop` (time = gap between chronologically
sorted Start/Stop events) and `Mynatime.Client.NewActivityItemPage` (explicit
decimal-hour duration in its URL-encoded form data).
"""

import argparse
import sys
from datetime import date, datetime
from urllib.parse import parse_qs


def load_profile(path):
    import json
    # profile.json files carry a UTF-8 BOM.
    with open(path, encoding="utf-8-sig") as handle:
        return json.load(handle)


def build_category_map(profile):
    """CategoryId -> display name."""
    items = (profile.get("Data") or {}).get("ActivityCategories") or {}
    result = {}
    for cat in items.get("Items", []):
        result[str(cat.get("Id"))] = cat.get("Name") or str(cat.get("Id"))
    return result


def parse_time(value):
    """Parse an ISO timestamp (with offset) to an aware/naive datetime, or None."""
    if not value:
        return None
    text = value.replace("Z", "+00:00")
    try:
        return datetime.fromisoformat(text)
    except ValueError:
        return None


class Span:
    """One chunk of tracked time attributed to a category."""

    __slots__ = ("category_id", "comment", "day", "hours")

    def __init__(self, category_id, comment, day, hours):
        self.category_id = str(category_id) if category_id is not None else None
        self.comment = comment or ""
        self.day = day  # date or None
        self.hours = hours


def spans_from_start_stop(item):
    """Yield spans from an ActivityStartStop item.

    Events are not stored in chronological order, so sort by time first; each Start
    contributes the interval from its own time to the next event's time.
    """
    events = [event for event in item.get("Events", []) if parse_time(event.get("Time"))]
    events.sort(key=lambda event: parse_time(event["Time"]))
    for current, following in zip(events, events[1:]):
        if current.get("Mode") != "Start":
            continue
        start = parse_time(current["Time"])
        end = parse_time(following["Time"])
        # A start/stop session lives within one day. If the next event is on a
        # later day, this Start was never closed (e.g. a stray backfilled date) —
        # don't stretch it across the gap; treat it as unclosed and skip it.
        if start.date() != end.date():
            continue
        hours = (end - start).total_seconds() / 3600.0
        if hours <= 0:
            continue
        yield Span(current.get("CategoryId"), current.get("Comment"), start.date(), hours)


def spans_from_new_activity(item):
    """Yield a single span from a NewActivityItemPage item (explicit duration)."""
    form = parse_qs(item.get("FormData", ""), keep_blank_values=True)

    def field(name):
        values = form.get(f"create[{name}]", [""])
        return values[0] if values else ""

    category_id = field("task") or None
    comment = field("comment")
    day = None
    raw_day = field("dateStart")
    if raw_day:
        try:
            day = date.fromisoformat(raw_day)
        except ValueError:
            day = None

    hours = None
    raw_duration = field("duration").strip().replace(",", ".")
    if raw_duration:
        try:
            hours = float(raw_duration)
        except ValueError:
            hours = None
    if hours is None:
        # Fall back to inAt -> outAt clock times if no explicit duration.
        start = parse_time_of_day(field("inAt"))
        end = parse_time_of_day(field("outAt"))
        if start is not None and end is not None and end > start:
            hours = (end - start) / 3600.0

    if hours:
        yield Span(category_id, comment, day, hours)


def parse_time_of_day(value):
    """Parse a HH:MM clock string to seconds-since-midnight, or None."""
    if not value:
        return None
    try:
        parts = value.split(":")
        return int(parts[0]) * 3600 + int(parts[1]) * 60
    except (ValueError, IndexError):
        return None


def collect_spans(profile):
    for item in (profile.get("Commits") or {}).get("Items", []):
        object_type = item.get("ObjectType")
        if object_type == "MynatimeCLI.ActivityStartStop":
            yield from spans_from_start_stop(item)
        elif object_type == "Mynatime.Client.NewActivityItemPage":
            yield from spans_from_new_activity(item)


def matches(span, categories, args, category_filter, comment_filter, from_day, to_day):
    if category_filter:
        name = categories.get(span.category_id, "").lower()
        if category_filter != span.category_id and category_filter.lower() not in name:
            return False
    if comment_filter and comment_filter.lower() not in span.comment.lower():
        return False
    if from_day and (span.day is None or span.day < from_day):
        return False
    if to_day and (span.day is None or span.day > to_day):
        return False
    return True


def parse_day_arg(value, label):
    if not value:
        return None
    try:
        return date.fromisoformat(value)
    except ValueError:
        sys.exit(f"error: --{label} must be YYYY-MM-DD, got {value!r}")


def main(argv=None):
    parser = argparse.ArgumentParser(description="Total the time spent on matching activities in a Mynatime profile.")
    parser.add_argument("-p", "--profile", required=True, help="path to the profile.json to read")
    parser.add_argument("--category", help="category name substring or exact CategoryId")
    parser.add_argument("--comment", help="substring to match in the activity comment")
    parser.add_argument("--from", dest="from_day", help="only activities on/after this date (YYYY-MM-DD)")
    parser.add_argument("--to", dest="to_day", help="only activities on/before this date (YYYY-MM-DD)")
    args = parser.parse_args(argv)

    from_day = parse_day_arg(args.from_day, "from")
    to_day = parse_day_arg(args.to_day, "to")

    profile = load_profile(args.profile)
    categories = build_category_map(profile)

    per_category = {}  # category_id -> [hours, count]
    total_hours = 0.0
    total_count = 0
    for span in collect_spans(profile):
        if not matches(span, categories, args, args.category, args.comment, from_day, to_day):
            continue
        bucket = per_category.setdefault(span.category_id, [0.0, 0])
        bucket[0] += span.hours
        bucket[1] += 1
        total_hours += span.hours
        total_count += 1

    filters = []
    if args.category:
        filters.append(f"category~{args.category!r}")
    if args.comment:
        filters.append(f"comment~{args.comment!r}")
    if from_day:
        filters.append(f"from {from_day}")
    if to_day:
        filters.append(f"to {to_day}")
    print(f"Filters: {', '.join(filters) if filters else '(none)'}")
    print(f"Matched {total_count} activit{'y' if total_count == 1 else 'ies'}")
    print()

    if per_category:
        width = max(len(categories.get(cid, str(cid))) for cid in per_category)
        for cid, (hours, count) in sorted(per_category.items(), key=lambda kv: kv[1][0], reverse=True):
            name = categories.get(cid, str(cid))
            print(f"  {name:<{width}}  {hours:7.2f} h  ({count})")
        print()
    print(f"TOTAL: {total_hours:.2f} h")


if __name__ == "__main__":
    main()
